const toRad = d => d * Math.PI / 180;

// Device location (San Francisco, CA)
const lat1 = 37.7749, lon1 = -122.4194;

// Shipping address: Boston, MA 02118 (approximate coords)
const lat2 = 42.3388, lon2 = -71.0685;

// Haversine formula
const R = 6371; // Earth's radius in km
const dlat = toRad(lat2 - lat1);
const dlon = toRad(lon2 - lon1);
const a = Math.sin(dlat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dlon/2)**2;
const c = 2 * Math.asin(Math.sqrt(a));

const distKm = R * c;
const distMi = distKm * 0.621371;

console.log('=== Distance Estimate ===');
console.log('From: San Francisco, CA (37.7749°N, 122.4194°W)');
console.log('To:   4829 Elm Ridge Way, Suite 7, Boston, MA 02118 (~42.3388°N, 71.0685°W)');
console.log('');
console.log('Straight-line (great-circle) distance:');
console.log('  ' + distKm.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' km');
console.log('  ' + distMi.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' miles');
console.log('');
console.log('Estimated driving distance (typically ~15-30% longer):');
console.log('  ~' + Math.round(distMi*1.2).toLocaleString() + ' – ' + Math.round(distMi*1.3).toLocaleString() + ' miles');
"
